import {createRequire} from 'node:module';import {readFile,mkdir} from 'node:fs/promises';import assert from 'node:assert/strict';import http from 'node:http';import {createAFMDServer} from '../server.mjs';import path from 'node:path';
const {chromium}=createRequire(import.meta.url)('playwright');const root=path.resolve('extension');const files=['dashboard.html','app.js','model.js','style.css','icon.png','fonts/Montserrat.ttf','fonts/LibreCaslonText-Regular.ttf','popup.html','popup.js','background.js'];for(const file of files)await readFile(path.join(root,file));
const server=http.createServer(async(req,res)=>{try{const file=path.resolve(root,'.'+new URL(req.url,'http://localhost').pathname);if(!file.startsWith(root+path.sep))throw Error();let body=await readFile(file);const ext=path.extname(file);res.setHeader('Content-Type',({'.js':'text/javascript','.html':'text/html','.css':'text/css','.ttf':'font/ttf','.png':'image/png'})[ext]||'application/octet-stream');if(file.endsWith('/app.js'))body=body.toString().replace("location.protocol==='chrome-extension:'&&Boolean(globalThis.chrome?.runtime?.id)","Boolean(globalThis.chrome?.runtime?.id)");res.end(body);}catch{res.writeHead(404);res.end();}});await new Promise(r=>server.listen(4174,'127.0.0.1',r));
const fixtureToken='fixture-access-token-for-browser-123456789';let audioCalls=0,summaryCalls=0;const apiServer=createAFMDServer({env:{AFMD_ACCESS_TOKEN:fixtureToken,AFMD_AI_KEY:'fixture-provider-key-not-real'},fetchAI:async(url,options)=>{assert.equal(options.headers.Authorization,'Bearer fixture-provider-key-not-real');if(url.endsWith('/audio/transcriptions')){audioCalls++;if(audioCalls===1)return {ok:false,status:429};return {ok:true,json:async()=>({text:'Ana: Revisar a proposta até sexta.'})};}summaryCalls++;return {ok:true,json:async()=>({choices:[{message:{content:'Documento gerado no teste controlado.'}}]})};}});await new Promise(r=>apiServer.listen(0,'127.0.0.1',r));const apiURL='http://127.0.0.1:'+apiServer.address().port;
const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--use-fake-device-for-media-stream','--use-fake-ui-for-media-stream']});
try{const page=await browser.newPage({viewport:{width:1440,height:1024}});const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.addInitScript(()=>{const listeners=[];const stored={};const session={};window.__afmdFixture={put:async(id,value)=>{stored[id]=value;listeners.forEach(fn=>fn());}};window.chrome={runtime:{id:'afmd-fixture',getURL:p=>p},permissions:{request:async()=>true},storage:{local:{get:async()=>stored},session:{get:async()=>session,set:async values=>{Object.assign(session,values);listeners.forEach(fn=>fn(values,'session'));},remove:async key=>{delete session[key];listeners.forEach(fn=>fn({},'session'));}},onChanged:{addListener:fn=>listeners.push(fn)}}};});
await page.goto('http://127.0.0.1:4174/dashboard.html');await page.getByRole('heading',{name:'Minhas transcrições',exact:true}).waitFor();await page.getByRole('button',{name:'Clientes',exact:true}).click();await page.getByRole('button',{name:'Novo cliente'}).click();await page.locator('#client-name').fill('Clínica Horizonte');await page.getByRole('button',{name:'Salvar cliente'}).click();await page.getByRole('button',{name:'Minhas transcrições',exact:true}).click();
const capture={format:'afmd-meet-v1',title:'Alinhamento Clínica Horizonte',started:'2026-11-01T14:00:00Z',running:false,segments:[{time:'00:12',speaker:'Ana',text:'Precisamos revisar a proposta até sexta.'},{time:'00:24',speaker:'Mariana',text:'Eu envio o material para a equipe.'}]};
await page.evaluate(c=>window.__afmdFixture.put('afmd-meet-fixture',c),capture);await page.getByRole('heading',{name:capture.title,exact:true}).waitFor();assert.equal(await page.locator('#assign-client option:checked').textContent(),'Clínica Horizonte');assert.match(await page.locator('.document').textContent(),/00:24.*Mariana/);await page.evaluate(c=>window.__afmdFixture.put('afmd-meet-fixture',c),capture);await page.waitForTimeout(100);assert.equal(await page.locator('.meeting').count(),1);
await page.getByRole('button',{name:'Resumo',exact:true}).click();await page.getByRole('button',{name:'Gerar resumo',exact:true}).click();await page.getByRole('status').filter({hasText:'Serviço de IA ainda não conectado'}).waitFor();await page.getByRole('button',{name:'Transcrição',exact:true}).click();await page.locator('#notice').evaluate(e=>e.textContent='');await page.screenshot({path:'test-results/extension-dashboard.png',fullPage:true});await page.getByRole('button',{name:'Clientes',exact:true}).click();await page.screenshot({path:'test-results/extension-clients.png',fullPage:true});
// Real private API, synthetic microphone, simulated provider: no external data or billing.
await page.route(apiURL+'/**',async route=>{const request=route.request();const response=await fetch(request.url(),{method:request.method(),headers:{Authorization:request.headers().authorization||'','Content-Type':request.headers()['content-type']||'application/json',Origin:'chrome-extension://'+'a'.repeat(32)},body:request.postDataBuffer()||undefined});await route.fulfill({status:response.status,contentType:'application/json',body:await response.text()});});
await page.getByRole('button',{name:'Configurações',exact:true}).click();await page.locator('#service-url').fill(apiURL);await page.locator('#service-token').fill(fixtureToken);await page.getByRole('button',{name:'Conectar serviço seguro',exact:true}).click();await page.getByText('Serviço seguro conectado',{exact:true}).waitFor();assert.equal(await page.evaluate(()=>localStorage.getItem('afmd-v1').includes('fixture-access-token')),false);
await page.getByRole('button',{name:'Iniciar transcrição',exact:true}).click();await page.locator('#record-title').fill('Gravação de teste');await page.locator('#consent').check();await page.getByRole('button',{name:'Gravar microfone',exact:true}).click();await page.waitForFunction(()=>document.querySelector('#record-status').textContent.startsWith('Gravando.'));await page.waitForTimeout(300);await page.getByRole('button',{name:'Encerrar e transcrever',exact:true}).click();await page.getByRole('status').filter({hasText:'saldo insuficiente'}).waitFor();await page.locator('#record-download').waitFor({state:'visible'});assert.match(await page.locator('#record-audio').getAttribute('src'),/^blob:/);await page.getByRole('button',{name:'Transcrever gravação disponível',exact:true}).click();await page.getByRole('heading',{name:'Gravação de teste',exact:true}).waitFor();assert.equal(audioCalls,2);assert.match(await page.locator('.document').textContent(),/Ana: Revisar/);
await page.getByRole('button',{name:'Resumo',exact:true}).click();await page.getByRole('button',{name:'Gerar resumo',exact:true}).click();await page.getByText('Documento gerado no teste controlado.',{exact:true}).waitFor();assert.equal(summaryCalls,1);
await page.getByRole('button',{name:'Configurações',exact:true}).click();await page.getByRole('button',{name:'Desconectar serviço',exact:true}).click();await page.getByText('Serviço de IA não conectado',{exact:true}).waitFor();
const popup=await browser.newPage();await popup.addInitScript(()=>{window.chrome={runtime:{getURL:p=>'chrome-extension://fixture/'+p},tabs:{query:async(q,cb)=>cb([{url:'https://example.org'}]),create:arg=>window.__opened=arg}};});await popup.goto('http://127.0.0.1:4174/popup.html');await popup.getByRole('button',{name:'Abrir painel AFMD'}).click();assert.equal(await popup.evaluate(()=>window.__opened.url),'chrome-extension://fixture/dashboard.html');assert.deepEqual(errors,[]);console.log('PASS: painel, captura importada, deduplicação, cliente, conexão autenticada por sessão, código ausente do histórico, microfone sintético, preservação do áudio após falha e nova tentativa até transcrição salva pela API com provedor simulado, resumo e desconexão. IA externa e instalação MV3 real não validadas.');
}finally{await browser.close();await new Promise(r=>server.close(r));await new Promise(r=>apiServer.close(r));}
